AUTH_FLOW_TEXT = [
    ("Three-Guard Architecture",
     "Laravel uses three separate authentication guards configured in config/auth.php. Each guard has its own "
     "provider (Eloquent model), session driver, and password broker. The 'web' guard authenticates users from "
     "the users table. The 'admin' guard authenticates admins from the admins table. The 'reviewer' guard "
     "authenticates reviewers from the reviewers table. Sessions are isolated — logging in as admin does NOT "
     "log in as user, and vice versa. NestJS migration must replicate this with three separate JWT strategies: "
     "UserJwtStrategy, AdminJwtStrategy, ReviewerJwtStrategy. Each issues JWTs signed with a different secret "
     "(or different audience claim) to prevent cross-role token reuse."),
    ("Login Flow (User)",
     "User visits /login → LoginController@showLoginForm. Submits credentials → LoginController@login. "
     "Controller calls findUsername() to detect email vs username. Validates (required|string) for username "
     "field, (required|string) for password. Verifies captcha via verifyCaptcha() helper. Stores "
     "pre_login_session_id in session for cart transfer. Throttles login attempts via hasTooManyLoginAttempts() "
     "(5 attempts per minute by default). On success: attemptLogin() fires, authenticated() hook runs. "
     "authenticated() does: (1) saves UserLogin record with IP/geo/browser/OS, (2) calls transferCartItemsToUser() "
     "to merge guest cart into user cart, (3) checks checkout_return_url session — if set, redirects there, "
     "(4) else calls Intended::getRedirection() for intended URL, (5) else redirects to /dashboard."),
    ("Registration Flow",
     "User visits /register → RegisterController@showRegistrationForm. If gs('registration')=0: shows "
     "registration_disabled view. Submits form → RegisterController@register. Validates: firstname (required), "
     "lastname (required), email (required|email|unique:users), password (required|confirmed|min:6, with "
     "mixedCase/numbers/symbols/uncompromised rules if gs('secure_password')=1), captcha (sometimes|required), "
     "agree (required if gs('agree')=1). Regenerates session token. Verifies captcha. Stores "
     "pre_register_session_id. Creates User via create() method: lowercases email, Hash::make(password), sets "
     "ref_by from session 'reference' (referral system), sets kv/ev/sv based on whether KYC/email/mobile "
     "verification is enabled (if disabled, auto-marks as verified). Creates AdminNotification. Creates UserLogin. "
     "Fires Registered event. Logs in user. Calls registered() hook which: transfers cart, checks "
     "checkout_return_url, redirects to /user-data if profile incomplete, else dashboard."),
    ("Email Verification",
     "If gs('ev')=1 (email verification enabled): new user has ev=0. After login, CheckStatus middleware detects "
     "ev=0 and redirects to /authorization. AuthorizationController@authorizeForm shows verification form. User "
     "requests code via /resend-verify/email → sendVerifyCode() generates 6-digit code, stores in user.ver_code, "
     "stores timestamp in user.ver_code_send_at, sends email. User submits code via /verify-email → "
     "emailVerification() checks code + expiry (10 min default), sets ev=1."),
    ("Mobile Verification",
     "Same as email but for mobile (sv field). Uses 6-digit SMS code. Requires SMS gateway configured "
     "(Twilio/Nexmo/etc. in general_settings.sms_config). Currently disabled (sv=0 in settings)."),
    ("2FA (Google Authenticator)",
     "User enables via /user/twofactor → create2fa() generates secret, stores in user.tsc, shows QR code. User "
     "scans with Google Authenticator app, enters code → verifyG2fa() validates TOTP, sets ts=1 (enabled). "
     "On subsequent logins: authenticated() sets tv=0 (2FA unverified). CheckStatus middleware detects ts=1 AND "
     "tv=0, redirects to /authorization. User enters TOTP code → g2faVerification() validates, sets tv=1."),
    ("KYC Verification",
     "Required for withdrawals (KycMiddleware). User visits /user/kyc-form → kycForm() shows KYC form (configurable "
     "fields via admin). Submits documents → kycSubmit() stores in user.kyc_data JSON, sets kv=2 (PENDING). "
     "Admin reviews via /admin/users/kyc-data/{id} → approves (kv=1) or rejects (kv=0 + kyc_rejection_reason). "
     "Currently disabled (kv=0 in settings) but code is fully functional."),
    ("Password Reset Flow",
     "User visits /password/reset → ForgotPasswordController@sendResetCodeEmail. Generates 6-digit code, stores in "
     "password_resets table (or admin_password_resets / reviewer_password_resets depending on guard), emails code. "
     "User visits /password/code-verify → enters code → verifyCode() validates. User visits /password/reset/{token} "
     "→ ResetPasswordController@showResetForm. Submits new password → reset() updates user password."),
    ("OAuth (Socialite)",
     "User clicks 'Login with Google' on /login → SocialiteController@socialLogin('google') → SocialLogin library "
     "redirects to Google. Google redirects back to /social-login/callback/google → SocialiteController@callback → "
     "SocialLogin::login(). Library: (1) fetches Google user, (2) checks if user with that google_id exists, "
     "(3) if yes: logs in, (4) if no: creates new user with google data, logs in. Facebook and LinkedIn configured "
     "but disabled (status=0 in socialite_credentials)."),
    ("Impersonation",
     "Admin can 'login as user' via /admin/users/login/{id} → ManageUsersController@login(). Admin can 'login as "
     "reviewer' via /admin/reviewers/login/{id} → ManageReviewerController@loginAsReviewer(). These endpoints log "
     "in the target user/reviewer using Laravel's Auth::login() method. No separate impersonation token — admin "
     "session is replaced. To return, admin must log out and log back in as admin. NestJS migration should "
     "implement this with a proper impersonation token (e.g., JWT with impersonated_by claim) for better audit "
     "trail and easier return-to-admin flow."),
    ("Cart Transfer on Login/Register",
     "Critical UX feature: guest cart items are NOT lost when user logs in or registers. Before login: "
     "pre_login_session_id stored in session. After login: transferCartItemsToUser() iterates session cart items. "
     "For each: if user already has same product in cart, merge addon flags (reskin/publish/store_optimization/"
     "extended) and delete session row; else update row to set user_id, null session_id. Same flow on registration. "
     "NestJS migration must replicate this — store guest cart in Redis keyed by session ID, merge into user cart "
     "on auth success."),
]

